export function registriereLicht(Alpine) {
  const fein = matchMedia('(hover: hover) and (pointer: fine)');
  const erlaubt = () => fein.matches && !bewegungRuhig()
    && document.documentElement.dataset.transparenz !== 'reduziert'
    && document.documentElement.dataset.fenster !== 'inaktiv';
  Alpine.directive('np-licht', (el) => {
    const glanz = el.querySelector(':scope > .np-glanz');
    if (!glanz) return;
    let r = null, rahmen = 0, x = 50, y = 0;
    const setze = (k, v) => glanz.style.setProperty(k, v);
    el.addEventListener('pointerenter', () => { if (!erlaubt()) return; r = el.getBoundingClientRect(); setze('--np-licht', '1'); });
    el.addEventListener('pointermove', (e) => {
      if (!r) return;
      x = ((e.clientX - r.left) / r.width) * 100; y = ((e.clientY - r.top) / r.height) * 100;
      rahmen ||= requestAnimationFrame(() => { rahmen = 0; setze('--np-licht-x', x + '%'); setze('--np-licht-y', y + '%'); });
    }, { passive: true });
    el.addEventListener('pointerdown', () => r && setze('--np-licht', '1.6'));
    el.addEventListener('pointerup', () => r && setze('--np-licht', '1'));
    el.addEventListener('pointerleave', () => { r = null; setze('--np-licht', '0'); });
  });
}
export function registriereFenster() {
  const html = document.documentElement;
  const setze = () => { html.dataset.fenster = document.hasFocus() && !document.hidden ? 'aktiv' : 'inaktiv'; };
  addEventListener('focus', setze); addEventListener('blur', setze);
  document.addEventListener('visibilitychange', setze); setze();
}
