Alpine.data('npChart', (typ, daten, optionen = {}) => ({
  chart: null, i: 0,
  zeichne(d) { return this.chart ? this.setze(d) : this.baue(d); },
  setze(d) {
    const neu = BAUER[typ](d, optionen);
    if (neu.data.datasets.length !== this.chart.data.datasets.length) return this.baue(d);
    this.chart.data.labels = neu.data.labels;
    neu.data.datasets.forEach((ds, k) => Object.assign(this.chart.data.datasets[k], ds));
    this.chart.update(bewegungRuhig() ? 'none' : undefined);
    if (this.$refs.ansage) this.$refs.ansage.textContent = d.fazit ?? '';
  },
  tasten(e) {
    const n = this.chart.data.labels.length;
    const ziel = { ArrowRight: this.i + 1, ArrowLeft: this.i - 1, Home: 0, End: n - 1 }[e.key];
    if (ziel === undefined) return;
    e.preventDefault(); this.i = Math.max(0, Math.min(n - 1, ziel));
    const aktiv = [{ datasetIndex: 0, index: this.i }];
    this.chart.setActiveElements(aktiv); this.chart.tooltip.setActiveElements(aktiv, { x: 0, y: 0 });
    this.chart.update('none');
  },
}));
// in basis():
