        $zeitraum = in_array($r->query('zeitraum'), self::ZEITRAUM, true) ? $r->query('zeitraum') : 'semester';
        $kategorie = in_array((int) $r->query('kategorie'), $erlaubt['kategorien'] ?? [], true) ? (int) $r->query('kategorie') : null;
        $wochen = in_array((int) $r->query('wochen'), self::WOCHEN, true) ? (int) $r->query('wochen') : 12;
        return new self($zeitraum, $kategorie, /* … */ $wochen);
    }
