Alpine.data('npFilter', (start) => ({
  f: start,
  async setze(k, v) {
    this.f[k] = v;
    const url = new URL(location.href);
    for (const [a, b] of Object.entries(this.f)) (b === null || b === '') ? url.searchParams.delete(a) : url.searchParams.set(a, b);
    history.replaceState(history.state, '', url);
    const antwort = await fetch(url, { headers: { Accept: 'application/json', 'X-Requested-With': 'XMLHttpRequest' }, credentials: 'same-origin' });
    if (!antwort.ok) return window.npToast?.(t('statistik.fehler'), 'error');
    this.$dispatch('np-daten', await antwort.json());
  },
}));

